import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import FieldSet from 'flarum/common/components/FieldSet';
import Form from 'flarum/common/components/Form';
import ItemList from 'flarum/common/utils/ItemList';
import { NUMBER_BOUNDS, SETTING, settingKey, trans, transText } from '../config';

/** Anything `buildSettingComponent` accepts beyond what `field()` derives from a name. */

/**
 * The extension's settings, grouped. Core renders registered settings as one
 * flat column, which gives no sign that two of these decide which links the
 * other seven ever get to describe.
 */
export default class LinkPreviewSettingsPage extends ExtensionPage {
  content() {
    return m("div", {
      className: "ExtensionPage-settings"
    }, m("div", {
      className: "container"
    }, m(Form, null, this.settingSections().toArray(), m("div", {
      className: "Form-group Form-controls"
    }, this.submitButton(), this.resetButton(
    // Core's default reads the `settingLabels` that `field()` fills,
    // so the modal lists settings by name rather than by key.
    undefined, app.translator.trans('core.admin.extension.reset_settings.title_extension', {
      extensionTitle: this.extension.extra['flarum-extension'].title
    }, true), this.extension.id)))));
  }
  saveSettings(e) {
    // Submitting does not always take focus off a field first.
    Object.keys(NUMBER_BOUNDS).forEach(name => this.clampNumber(name));
    return super.saveSettings(e);
  }

  /**
   * Nothing enforces `min` on a number input and an emptied one saves as an
   * empty row, while the server clamps both back into range on every read. The
   * field would otherwise show a number the forum ignores.
   */
  clampNumber(name) {
    const {
      min,
      fallback
    } = NUMBER_BOUNDS[name];
    const setting = this.setting(settingKey(name));
    // A setting nobody has saved yet arrives from the payload as the number
    // the extender declared, not as a string.
    const raw = String(setting() ?? '').trim();
    const clamped = raw === '' || !Number.isFinite(Number(raw)) ? fallback : Math.max(min, Math.trunc(Number(raw)));

    // Only on a real change, so tabbing through an untouched field does not
    // light up the submit button.
    if (String(clamped) !== raw) {
      setting(String(clamped));
    }
  }

  /**
   * `buildSettingComponent` records nothing about what it built, so the label
   * is registered alongside the stream; otherwise the reset modal lists these
   * settings by their storage keys.
   */
  field(name, options) {
    const key = settingKey(name);
    const label = trans(`settings.${name}_label`);
    const bounds = NUMBER_BOUNDS[name];
    this.setting(key, '', label);
    return this.buildSettingComponent({
      setting: key,
      label,
      help: trans(`settings.${name}_help`),
      ...(bounds ? {
        min: bounds.min,
        onblur: () => this.clampNumber(name)
      } : {}),
      ...options
    });
  }

  /**
   * An `ItemList` so another extension can slot a section of its own between
   * these, which is the only way into a page that draws its own fields.
   *
   * `FieldSet--form` on every section: without it core spaces fieldset items
   * 5px apart and label to help text 10px, so each help text sits closer to
   * the next field than to the one it describes.
   */
  settingSections() {
    const items = new ItemList();
    items.add('appearance', m(FieldSet, {
      className: "FieldSet--form",
      label: transText('sections.appearance_label'),
      description: transText('sections.appearance_description')
    }, this.field(SETTING.openLinksInNewTab, {
      type: 'bool'
    }), this.field(SETTING.googleFaviconFallback, {
      type: 'bool'
    })), 100);
    items.add('behaviour', m(FieldSet, {
      className: "FieldSet--form",
      label: transText('sections.behaviour_label'),
      description: transText('sections.behaviour_description')
    }, this.field(SETTING.previewInternalLinks, {
      type: 'bool'
    }), this.field(SETTING.skipMediaLinks, {
      type: 'bool'
    }), this.field(SETTING.maxPreviewsPerPost, {
      type: 'number'
    })), 90);
    items.add('performance', m(FieldSet, {
      className: "FieldSet--form",
      label: transText('sections.performance_label'),
      description: transText('sections.performance_description')
    }, this.field(SETTING.enableBatchRequests, {
      type: 'bool'
    }), this.field(SETTING.cacheTime, {
      type: 'number'
    })), 80);
    items.add('filtering', m(FieldSet, {
      className: "FieldSet--form",
      label: transText('sections.filtering_label'),
      description: transText('sections.filtering_description')
    }, this.field(SETTING.allowlist, {
      type: 'textarea',
      placeholder: transText('settings.allowlist_placeholder')
    }), this.field(SETTING.blocklist, {
      type: 'textarea',
      placeholder: transText('settings.blocklist_placeholder')
    })), 70);

    // Core's `content()` renders whatever another extension registered against
    // this one, and replacing that method would silently drop them.
    const registered = app.registry.getSettings(this.extension.id) ?? [];
    if (registered.length) {
      items.add('registered', registered.map(entry => {
        if (typeof entry !== 'function') {
          this.setting(entry.setting, '', entry.label);
        }
        return this.buildSettingComponent(entry);
      }), 0);
    }
    return items;
  }
}
flarum.reg.add('datlechin-link-preview', 'admin/components/LinkPreviewSettingsPage', LinkPreviewSettingsPage);